          // close current visit
          const len = prev - start;
          if (len > longest) longest = len;
          visits += 1;

          // start a new visit
          start = ts;
          prev = ts;
        }
      }

      // close the final visit
      const finalLen = prev - start;
      if (finalLen > longest) longest = finalLen;
      visits += 1;

      result.push([uid, visits, longest]);
    }
  }

  return result;
}
